const J2 = (a) => a.join(" ");
const N2 = (t) => t.trim().split(/\s+/).filter(Boolean).map(Number);

SHAPES.arr2 = SHAPES.arr2 ?? {
  py: "n = int(data[0])\na = list(map(int, data[1:1 + n]))\nb = list(map(int, data[1 + n:1 + 2 * n]))\n",
  cpp: "int n;cin>>n;vector<long long>a(n),b(n);for(auto&x:a)cin>>x;for(auto&x:b)cin>>x;",
  c: "int n,i;static long long a[500005],b[500005];if(scanf(\"%d\",&n)!=1)return 1;for(i=0;i<n;i++)scanf(\"%lld\",&a[i]);for(i=0;i<n;i++)scanf(\"%lld\",&b[i]);",
  parse: (t) => { const v = N2(t); const n = v[0]; return { n, a: v.slice(1, 1 + n), b: v.slice(1 + n, 1 + 2 * n) }; },
  gen: (r, cfg) => { const n = r.int(cfg.nMin ?? 3, cfg.nMax ?? 8); const lo = cfg.lo ?? 0, hi = cfg.hi ?? 30; return `${n}\n${J2(r.intArray(n, lo, hi))}\n${J2(r.intArray(n, lo, hi))}\n`; },
};
const IFA = "第一行一个整数 $n$（$1 \\le n \\le 1000$）；第二行 $n$ 个整数 $a_i$，用空格隔开。";
const IFAK = "第一行一个整数 $n$；第二行 $n$ 个整数 $a_i$；第三行一个整数 $k$。";
const IFA2 = "第一行一个整数 $n$；接下来两行，每行 $n$ 个整数，表示数组 $a$ 和数组 $b$。";
const SA = "for(i=0;i<n;i++)for(int z=i+1;z<n;z++)";

function eop(o) {
  return makeFamily({
    shape: o.shape ?? "arr",
    op: { id: o.id, title: o.title, py: o.py, cpp: o.cpp, c: o.c, js: o.js, cppExtra: o.cppExtra, cExtra: o.cExtra },
    difficulty: "简单",
    topic: o.topic ?? "数组与排序",
    tags: o.tags ?? ["数组", "排序"],
    hint: o.hint ?? "",
    cfg: o.cfg ?? { nMin: 5, nMax: 12, lo: 0, hi: 50 },
    variant: 1,
    statement: o.desc,
    inputFormat: o.inputFormat ?? IFA,
    outputFormat: o.outputFormat ?? "一行，输出答案。",
    timeLimitMs: 1000,
  });
}
const jprime2 = (v) => { if (v < 2) return false; for (let d = 2; d * d <= v; d++) if (v % d === 0) return false; return true; };
const dsumjs = (v) => { let s = 0; while (v) { s += v % 10; v = Math.floor(v / 10); } return s; };
const DSUM_CPP = "long long ds(long long v){long long s=0;while(v){s+=v%10;v/=10;}return s;}";
const DSUM_PY = "def ds(v):\n    s = 0\n    while v:\n        s += v % 10\n        v //= 10\n    return s\n";

