const IFM = "第一行两个整数 $n, m$；接下来 $n$ 行，每行 $m$ 个整数。";
const EASY_E = [
  { id: "e-mat-row-max", title: "矩阵每行的最大值", desc: "按顺序输出矩阵每一行的最大值，用空格隔开。", shape: "matrix", cfg: { nMin: 2, nMax: 5, lo: 0, hi: 50 }, inputFormat: IFM,
    js: ({ g }) => g.map((r) => Math.max(...r)).join(" "), py: "print(*[max(r) for r in g])",
    cpp: 'for(int a1=0;a1<n;a1++){long long v=g[a1][0];for(int b1=1;b1<m;b1++)v=max(v,g[a1][b1]);cout<<v<<(a1+1<n?" ":"\\n");}',
    c: 'for(i=0;i<n;i++){long long v=g[i][0];for(z=1;z<m;z++)if(g[i][z]>v)v=g[i][z];printf("%lld%c",v,i+1<n?32:10);}' },
  { id: "e-mat-col-max", title: "矩阵每列的最大值", desc: "按顺序输出矩阵每一列的最大值，用空格隔开。", shape: "matrix", cfg: { nMin: 2, nMax: 5, lo: 0, hi: 50 }, inputFormat: IFM,
    js: ({ n, m, g }) => Array.from({ length: m }, (_, z) => Math.max(...g.map((r) => r[z]))).join(" "), py: "print(*[max(g[i][j] for i in range(n)) for j in range(m)])",
    cpp: 'for(int b1=0;b1<m;b1++){long long v=g[0][b1];for(int a1=1;a1<n;a1++)v=max(v,g[a1][b1]);cout<<v<<(b1+1<m?" ":"\\n");}',
    c: 'for(z=0;z<m;z++){long long v=g[0][z];for(i=1;i<n;i++)if(g[i][z]>v)v=g[i][z];printf("%lld%c",v,z+1<m?32:10);}' },
  { id: "e-mat-zigzag", title: "矩阵之字形输出", desc: "按之字形顺序输出矩阵元素：第 1 行从左到右、第 2 行从右到左，交替进行，元素之间用一个空格隔开。", shape: "matrix", cfg: { nMin: 2, nMax: 4, lo: 0, hi: 50 }, inputFormat: IFM,
    js: ({ g }) => g.flatMap((r, i) => (i % 2 === 0 ? r : r.slice().reverse())).join(" "),
    py: "out = []\nfor i, r in enumerate(g):\n    out.extend(r if i % 2 == 0 else r[::-1])\nprint(*out)",
    cpp: 'for(int a1=0;a1<n;a1++)for(int b1=0;b1<m;b1++){int j2=(a1%2==0)?b1:(m-1-b1);cout<<g[a1][j2]<<" ";}cout<<"\\n";',
    c: 'for(i=0;i<n;i++)for(z=0;z<m;z++){int j2=(i%2==0)?z:(m-1-z);printf("%lld ",g[i][j2]);}putchar(10);' },
  { id: "e-mat-saddle", title: "矩阵鞍点个数", desc: "若某个元素在它所在的行中最大、在它所在的列中最小，就称它为一个鞍点（方阵，行列可以同时有多个）。输出鞍点的个数。", shape: "matrix", cfg: { nMin: 2, nMax: 4, lo: 0, hi: 9 }, inputFormat: IFM,
    js: ({ n, g }) => { let c = 0; for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) { let isMax = true, isMin = true; for (let k = 0; k < n; k++) { if (g[i][k] > g[i][j]) isMax = false; if (g[k][j] < g[i][j]) isMin = false; } if (isMax && isMin) c++; } return `${c}`; },
    py: "c = 0\nfor i in range(n):\n    for j in range(n):\n        if all(g[i][k] <= g[i][j] for k in range(n)) and all(g[k][j] >= g[i][j] for k in range(n)):\n            c += 1\nprint(c)",
    cpp: 'int c=0;for(int a1=0;a1<n;a1++)for(int b1=0;b1<n;b1++){bool mx=true,mn=true;for(int k=0;k<n;k++){if(g[a1][k]>g[a1][b1])mx=false;if(g[k][b1]<g[a1][b1])mn=false;}if(mx&&mn)c++;}cout<<c<<"\\n";',
    c: 'long long c=0;for(i=0;i<n;i++)for(z=0;z<m;z++){int mx=1,mn=1,k;for(k=0;k<m;k++)if(g[i][k]>g[i][z])mx=0;for(k=0;k<n;k++)if(g[k][z]<g[i][z])mn=0;if(mx&&mn)c++;}printf("%lld\\n",c);' },
  { id: "e-mat-sort-rows", title: "矩阵每行升序排序", desc: "把矩阵的每一行单独按从小到大排序后输出。", shape: "matrix", cfg: { nMin: 2, nMax: 5, lo: 0, hi: 50 }, inputFormat: IFM,
    js: ({ g }) => g.map((r) => r.slice().sort((x, y) => x - y).join(" ")).join("\n"), py: "for r in g:\n    print(*sorted(r))",
    cpp: 'for(int a1=0;a1<n;a1++){sort(g[a1].begin(),g[a1].end());for(int b1=0;b1<m;b1++)cout<<g[a1][b1]<<(b1+1<m?" ":"\\n");}',
    c: 'for(i=0;i<n;i++){for(z=0;z<m;z++)for(int w=z+1;w<m;w++)if(g[i][w]<g[i][z]){long long t=g[i][z];g[i][z]=g[i][w];g[i][w]=t;}for(z=0;z<m;z++)printf("%lld%c",g[i][z],z+1<m?32:10);}' },
  { id: "e-mat-max-pos", title: "矩阵最大值的位置", desc: "输出最大值所在的行号和列号（均从 0 开始，按行优先取第一次出现的位置），用一个空格隔开。", shape: "matrix", cfg: { nMin: 2, nMax: 5, lo: 0, hi: 50 }, inputFormat: IFM,
    js: ({ n, m, g }) => { let bi = 0, bj = 0; for (let i = 0; i < n; i++) for (let j = 0; j < m; j++) if (g[i][j] > g[bi][bj]) { bi = i; bj = j; } return `${bi} ${bj}`; },
    py: "bi = bj = 0\nfor i in range(n):\n    for j in range(m):\n        if g[i][j] > g[bi][bj]:\n            bi, bj = i, j\nprint(bi, bj)",
    cpp: 'int bi=0,bj=0;for(int a1=0;a1<n;a1++)for(int b1=0;b1<m;b1++)if(g[a1][b1]>g[bi][bj]){bi=a1;bj=b1;}cout<<bi<<" "<<bj<<"\\n";',
    c: 'int bi=0,bj=0;for(i=0;i<n;i++)for(z=0;z<m;z++)if(g[i][z]>g[bi][bj]){bi=i;bj=z;}printf("%d %d\\n",bi,bj);' },
  { id: "e-mat-prime-count", title: "矩阵中质数的个数", desc: "输出矩阵中质数的个数。", shape: "matrix", cfg: { nMin: 2, nMax: 5, lo: 0, hi: 50 }, inputFormat: IFM,
    js: ({ g }) => { let c = 0; for (const r of g) for (const x of r) if (jprime2(x)) c++; return `${c}`; },
    py: "def isp(v):\n    if v < 2:\n        return False\n    d = 2\n    while d * d <= v:\n        if v % d == 0:\n            return False\n        d += 1\n    return True\nprint(sum(1 for r in g for x in r if isp(x)))",
    cpp: 'auto isp=[](long long v){if(v<2)return false;for(long long d=2;d*d<=v;d++)if(v%d==0)return false;return true;};int c=0;for(auto&r:g)for(auto x:r)if(isp(x))c++;cout<<c<<"\\n";',
    c: 'long long c=0;for(i=0;i<n;i++)for(z=0;z<m;z++){long long v=g[i][z],d;int ok=v>=2;for(d=2;d*d<=v;d++)if(v%d==0)ok=0;if(ok)c++;}printf("%lld\\n",c);' },
  { id: "e-mat-anti-diag", title: "矩阵副对角线元素", desc: "按从右上到左下的顺序输出矩阵副对角线上的元素，用空格隔开（方阵）。", shape: "matrix", cfg: { nMin: 2, nMax: 5, lo: 0, hi: 50 }, inputFormat: IFM,
    js: ({ n, g }) => Array.from({ length: n }, (_, i) => g[i][n - 1 - i]).join(" "), py: "print(*[g[i][n - 1 - i] for i in range(n)])",
    cpp: 'for(int a1=0;a1<n;a1++)cout<<g[a1][n-1-a1]<<(a1+1<n?" ":"\\n");', c: 'for(i=0;i<n;i++)printf("%lld%c",g[i][n-1-i],i+1<n?32:10);' },
  { id: "e-mat-reverse", title: "矩阵元素逆序输出", desc: "把矩阵所有元素按行优先的顺序倒过来，输出成一行。", shape: "matrix", cfg: { nMin: 2, nMax: 4, lo: 0, hi: 50 }, inputFormat: IFM,
    js: ({ n, m, g }) => { const o = []; for (let i = n - 1; i >= 0; i--) for (let j = m - 1; j >= 0; j--) o.push(g[i][j]); return o.join(" "); },
    py: "out = []\nfor i in range(n - 1, -1, -1):\n    for j in range(m - 1, -1, -1):\n        out.append(g[i][j])\nprint(*out)",
    cpp: 'for(int a1=n-1;a1>=0;a1--)for(int b1=m-1;b1>=0;b1--)cout<<g[a1][b1]<<" ";cout<<"\\n";',
    c: 'for(i=n-1;i>=0;i--)for(z=m-1;z>=0;z--)printf("%lld ",g[i][z]);putchar(10);' },
  { id: "e-mat-boundary-max", title: "矩阵边界元素的最大值", desc: "输出矩阵最外一圈元素中的最大值。", shape: "matrix", cfg: { nMin: 2, nMax: 5, lo: 0, hi: 50 }, inputFormat: IFM,
    js: ({ n, m, g }) => { let best = -Infinity; for (let i = 0; i < n; i++) for (let j = 0; j < m; j++) if (i === 0 || i === n - 1 || j === 0 || j === m - 1) best = Math.max(best, g[i][j]); return `${best}`; },
    py: "print(max(g[i][j] for i in range(n) for j in range(m) if i in (0, n - 1) or j in (0, m - 1)))",
    cpp: 'long long b=-1;for(int a1=0;a1<n;a1++)for(int b1=0;b1<m;b1++)if(a1==0||a1==n-1||b1==0||b1==m-1)b=max(b,g[a1][b1]);cout<<b<<"\\n";',
    c: 'long long b=-1;for(i=0;i<n;i++)for(z=0;z<m;z++)if(i==0||i==n-1||z==0||z==m-1)if(g[i][z]>b)b=g[i][z];printf("%lld\\n",b);' },
  { id: "e-mat-greater-than-avg", title: "矩阵中大于平均值的元素个数", desc: "输出矩阵中严格大于所有元素平均值的元素个数。", shape: "matrix", cfg: { nMin: 2, nMax: 5, lo: 0, hi: 60 }, inputFormat: IFM,
    js: ({ n, m, g }) => { const tot = g.flat().reduce((s, x) => s + x, 0), tot2 = n * m; return `${g.flat().filter((x) => x * tot2 > tot).length}`; },
    py: "tot = sum(sum(r) for r in g)\ncnt = 0\nfor r in g:\n    for x in r:\n        if x * n * m > tot:\n            cnt += 1\nprint(cnt)",
    cpp: 'long long tot=0;for(auto&r:g)for(auto x:r)tot+=x;int c=0;for(auto&r:g)for(auto x:r)if(x*n*m>tot)c++;cout<<c<<"\\n";',
    c: 'long long tot=0;for(i=0;i<n;i++)for(z=0;z<m;z++)tot+=g[i][z];long long c=0;for(i=0;i<n;i++)for(z=0;z<m;z++)if(g[i][z]*n*m>tot)c++;printf("%lld\\n",c);' },
  { id: "e-mat-even-sum", title: "矩阵中偶数元素之和", desc: "输出矩阵中所有偶数之和。", shape: "matrix", cfg: { nMin: 2, nMax: 5, lo: 0, hi: 50 }, inputFormat: IFM,
    js: ({ g }) => `${g.flat().filter((x) => x % 2 === 0).reduce((s, x) => s + x, 0)}`, py: "print(sum(x for r in g for x in r if x % 2 == 0))",
    cpp: 'long long s=0;for(auto&r:g)for(auto x:r)if(x%2==0)s+=x;cout<<s<<"\\n";', c: 'long long s=0;for(i=0;i<n;i++)for(z=0;z<m;z++)if(g[i][z]%2==0)s+=g[i][z];printf("%lld\\n",s);' },
];
export const easyFamilies = [...easyBase, ...EASY_A.map(eop), ...EASY_B.map(eop), ...EASY_C.map((o) => eop(Object.assign({ shape: 'str' }, o))), ...EASY_D.map((o) => eop(Object.assign({ shape: 'num' }, o))), ...EASY_E.map((o) => eop(Object.assign({ shape: 'matrix' }, o)))];
